// economy.ts — the crafting ECONOMY of the installed game (viewer/models/
// economy.json, generated by tools/extract_economy.py from the game's own
// modules/*/config.yaml).
//
// VIEW ▸ Build cost asks what the WHOLE craft costs in RAW materials — the
// parts (componentCosts below) AND the structure (buildCost: blocks, hull
// triangles, cables, frames, struts). The math is the game's own unfold rule
// (the one the dev viewer's cost panel and tools/game_data.py share — see
// MATRIX.md):
//   * `context: crafter` recipes only, the FIRST one producing an item wins;
//   * an item with no crafter recipe is TERMINAL: either a raw ore/molecule
//     (ARCHEAN_celestial.Iron …) or a catalog component nobody can craft
//     (`stuck` — the dev viewer's unresolved bucket: sensors, Dashboard …);
//   * quantities are the game's own units — celestial ores are GRAMS
//     (a SteelBeam = 9990 g iron + 10 g carbon), crafted items are counts.
// Nothing here renders; the widget only reads.
import { CELL, type Blueprint, type BlueprintComponent } from './format';
import { atlasJsonPaths } from './models';

export interface Recipe {
  /** recipe output batch (craft quantities may be fractional) */
  out: number;
  /** item id -> quantity consumed per batch */
  in: Record<string, number>;
  /** crafter seconds per batch */
  time?: number;
}

export interface Economy {
  recipes: Readonly<Record<string, Recipe>>;
  /** catalog component ids (module.Type) — decides raw vs `stuck` */
  components: readonly string[];
}

// ------------------------------------------------------------- item helpers
/** the game's construction module (blocks, cables, frames, rods …) */
const BUILD_MODULE = 'ARCHEAN_build';

/** display name of an item / ore / component (`ARCHEAN_celestial.Iron` → Iron) */
export function materialName(id: string): string {
  const i = id.lastIndexOf('.');
  return i < 0 ? id : id.slice(i + 1);
}

/** Terminal raw materials are stored in GRAMS (the game's crafting unit):
 *  the celestial ores AND the nuclear intermediates (YellowCake,
 *  PlutoniumDioxide … — they come from crushing/chemistry, not from a
 *  crafter, so the unfold stops there; `max_stack` 10 000 000 = 10 t marks
 *  them as mass, exactly like an ore). Crafted items/components count. */
export function isMassUnit(id: string): boolean {
  return id.startsWith('ARCHEAN_celestial.') || id.startsWith('ARCHEAN_nuclear.');
}

/** the blueprint's item id for one placed component (`module` rides the file) */
export function componentItemId(econ: Economy | null, c: BlueprintComponent): string {
  const mod = typeof c.module === 'string' ? c.module : '';
  if (mod) return `${mod}.${c.type}`;
  // no module field on the component record: resolve by type against the
  // recipe table (a suffix match is unambiguous in practice — `<mod>.<type>`)
  if (econ) {
    const hit = Object.keys(econ.recipes).find(k => k.endsWith(`.${c.type}`));
    if (hit) return hit;
  }
  return c.type;
}

// ---------------------------------------------------------------- expansion
export interface Cost {
  /** terminal raw materials (ore/molecule ids) -> quantity */
  raw: Record<string, number>;
  /** terminal CATALOG components with no crafter recipe */
  unresolved: Record<string, number>;
  /** summed crafter time of the unfolded recipes, seconds */
  time: number;
}

const add = (m: Record<string, number>, id: string, q: number) => {
  m[id] = (m[id] ?? 0) + q;
};

/** Unfold an item-count map through the crafter recipes (the game's
 *  RepairEconomy unfold: first recipe per output, per-branch cycle guard). */
export function expandToRaw(econ: Economy | null, items: Record<string, number>): Cost {
  const raw: Record<string, number> = {};
  const unresolved: Record<string, number> = {};
  let time = 0;
  const recipes = econ?.recipes ?? {};
  const visit = (id: string, qty: number, seen: ReadonlySet<string>) => {
    const rec = recipes[id];
    if (!rec || !(rec.out > 0) || seen.has(id)) {
      // terminal: a raw ore/molecule, or a catalog component nobody crafts
      add(rec || economyHas(econ, id) ? unresolved : raw, id, qty);
      return;
    }
    const batches = qty / rec.out;
    time += (rec.time ?? 0) * batches;
    const next = new Set(seen);
    next.add(id);
    for (const [k, v] of Object.entries(rec.in)) if (v > 0) visit(k, v * batches, next);
  };
  for (const [id, q] of Object.entries(items)) if (q > 0) visit(id, q, new Set());
  return { raw, unresolved, time };
}

/** one node of a component's recipe chain (the panel's expandable tree) */
export interface CostNode {
  id: string;
  /** quantity of THIS item (already multiplied down the chain) */
  qty: number;
  /** its own full raw expansion (independent of `children`) */
  cost: Cost;
  children: CostNode[];
  /** catalog component with no crafter recipe (nothing to unfold) */
  stuck: boolean;
  /** recursion stopped here on a cycle/depth cut (rare, defensive) */
  cut?: boolean;
}

const MAX_DEPTH = 12;

/** Build the recipe tree for `qty` of `id` (memo-free: the economy is tiny). */
export function costNode(econ: Economy | null, id: string, qty: number,
  seen: ReadonlySet<string> = new Set(), depth = 0): CostNode {
  const rec = econ?.recipes[id];
  const cost = expandToRaw(econ, { [id]: qty });
  const stuck = !rec && economyHas(econ, id);
  if (!rec || !(rec.out > 0) || seen.has(id) || depth >= MAX_DEPTH)
    return { id, qty, cost, children: [], stuck, cut: rec ? true : undefined };
  const next = new Set(seen);
  next.add(id);
  const scale = qty / rec.out;
  const children = Object.entries(rec.in).filter(([, v]) => v > 0)
    .map(([k, v]) => costNode(econ, k, v * scale, next, depth + 1));
  return { id, qty, cost, children, stuck };
}

function economyHas(econ: Economy | null, id: string): boolean {
  return !!econ && econ.components.includes(id);
}

/** crude "how much material" measure used for ORDERING (all game quantities
 *  are comparable units: grams for ores, counts for parts) */
export function materialQty(cost: Cost): number {
  let n = 0;
  for (const q of Object.values(cost.raw)) n += q;
  for (const q of Object.values(cost.unresolved)) n += q;
  return n;
}

// ---------------------------------------------------------- craft inventory
export interface CompEntry {
  /** item id (`module.Type`) */
  id: string;
  type: string;
  count: number;
  /** the part lives inside a subgrid (Build) — still a part you must build */
  nested: boolean;
  /** authored through a TOOL item rather than being an item itself
   *  (Dashboard boards arrive with the DashboardTool — see componentEntries) */
  viaTool?: boolean;
}

/** Every placed part, subgrid content INCLUDED (a nested Build's content is
 *  material you still have to craft — the breakdown must not hide it), with
 *  the Build construction ghosts themselves dropped (they are not items).
 *  A Dashboard BOARD is not an item either: the game's content list bills the
 *  DashboardTool instead — ONCE, however many boards the craft carries
 *  (tools/game_data.py `required_items` carries the same rule). */
export function componentEntries(econ: Economy | null, bp: Blueprint): CompEntry[] {
  const out = new Map<string, CompEntry>();
  let dashboards = 0;
  const walk = (comps: BlueprintComponent[], nested: boolean) => {
    for (const c of comps) {
      if (c.type === 'Build') {
        const sub = (c.data as { components?: BlueprintComponent[] } | undefined)?.components;
        if (Array.isArray(sub)) walk(sub, true);
        continue;
      }
      if (c.type === 'Dashboard') { dashboards++; continue; }
      const id = componentItemId(econ, c);
      const e = out.get(id) ?? { id, type: c.type, count: 0, nested: false };
      e.count++;
      e.nested ||= nested;
      out.set(id, e);
    }
  };
  walk(bp.data.components ?? [], false);
  if (dashboards) {
    const id = `${BUILD_MODULE}.DashboardTool`;
    out.set(id, { id, type: 'DashboardTool', count: 1, nested: false, viaTool: true });
  }
  return [...out.values()];
}

export interface CompCostRow extends CompEntry {
  /** the recipe chain for ONE unit of this part */
  unit: CostNode;
  /** raw material cost of ALL `count` units (the row's total contribution) */
  total: Cost;
}

export interface CraftCost {
  rows: CompCostRow[];
  /** sum over every part; `raw` = the craft's raw-material shopping list */
  total: Cost;
}

/** Per-part raw-material breakdown + the craft-wide totals. */
export function componentCosts(econ: Economy | null, bp: Blueprint): CraftCost {
  const rows: CompCostRow[] = componentEntries(econ, bp).map(e => {
    const unit = costNode(econ, e.id, 1);
    const total = expandToRaw(econ, { [e.id]: e.count });
    return { ...e, unit, total };
  });
  rows.sort((a, b) => materialQty(b.total) - materialQty(a.total) || b.count - a.count);
  const total: Cost = { raw: {}, unresolved: {}, time: 0 };
  for (const r of rows) {
    for (const [k, v] of Object.entries(r.total.raw)) add(total.raw, k, v);
    for (const [k, v] of Object.entries(r.total.unresolved)) add(total.unresolved, k, v);
    total.time += r.total.time;
  }
  return { rows, total };
}

// ------------------------------------------------- BUILD COST (everything)
// VIEW ▸ Build cost answers the FULL question, not just the parts: what do
// the blocks, the hull triangles, the cables, the frames and the struts ask
// for too? Every rule below is the game's own GetBlueprintContents, ported
// verbatim from tools/game_data.py `required_items` (the two MUST agree —
// economy.test.ts pins the corpus numbers):
//   * frames:  1 SteelBeam each ("1 beam per frame");
//   * blocks:  the FULL rect (sx+1)(sy+1)(sz+1) cells of the material's
//              block item (a shaped block still bills its bounding rect);
//   * triangles: area·0.05 m ÷ cell volume = area·3.2 block items, min 1
//              per triangle (a sliver still costs a block);
//   * struts:  ceil(length·100) SteelRod (1 rod = 1 cm);
//   * cables:  per PIPE SEGMENT trunc(length·100) of the class's spool item
//              — the game truncates SEGMENT BY SEGMENT (2 × 1.5 cm segments
//              cost 2 cm, not 3), and the spool recipe pays out 10 000 units
//              per batch, so 1 unit = 1 cm;
//   * parts:   1 each, subgrid content included, Build ghosts dropped, and
//              a Dashboard is not an item — its authoring tool is
//              (ARCHEAN_build.DashboardTool, one per craft).
export const OCCUPANCY_TYPE = 255;
/** hull prism thickness, m (the game draws/scales triangles at 0.05 m) */
export const TRIANGLE_THICKNESS = 0.05;
const CELL_VOLUME = CELL ** 3;
export const BLOCK_ITEMS = [
  'CompositeBlock', 'ConcreteBlock', 'SteelBlock', 'AluminiumBlock',
  'GlassBlock', 'LeadBlock', 'TitaniumBlock',
] as const;
export const PIPE_ITEMS: Readonly<Record<string, string>> = {
  data: 'DataCable', lowvoltage: 'LowVoltageCable',
  highvoltage: 'HighVoltageCable', fluid: 'FluidPipe', item: 'ItemConduit',
};

const blockItem = (material: unknown): string => {
  const m = typeof material === 'number' ? material : 0;
  return `${BUILD_MODULE}.${BLOCK_ITEMS[m >= 0 && m < BLOCK_ITEMS.length ? m : 0]}`;
};

/** the three lattice points of a hull triangle (FILE stores them FLAT:
 *  v0_x … v2_z — a legacy nested `v` array is still accepted) */
function triPoints(t: Record<string, unknown>): number[][] {
  const legacy = t.v;
  if (Array.isArray(legacy)) return legacy as number[][];
  return [0, 1, 2].map(i => ['x', 'y', 'z'].map(ax => Number(t[`v${i}_${ax}`]) || 0));
}

/** triangle area in m² — the frame offsets cancel in the edge differences,
 *  so the 0.25 m pitch alone maps the lattice ints to metres */
export function triangleArea(p: number[][]): number {
  const [p0, p1, p2] = p as [number[], number[], number[]];
  const ax = (p1[0]! - p0[0]!) * CELL, ay = (p1[1]! - p0[1]!) * CELL, az = (p1[2]! - p0[2]!) * CELL;
  const bx = (p2[0]! - p0[0]!) * CELL, by = (p2[1]! - p0[1]!) * CELL, bz = (p2[2]! - p0[2]!) * CELL;
  const cx = ay * bz - az * by, cy = az * bx - ax * bz, cz = ax * by - ay * bx;
  return 0.5 * Math.sqrt(cx * cx + cy * cy + cz * cz);
}

/** where an item's quantity came from — the row's own physical measure */
export interface ItemMeasure {
  /** block cells (blocks) / cells' worth of volume (triangles) */
  cells?: number;
  /** physical length in metres (cables, struts) */
  metres?: number;
  /** hull triangle count + their total area */
  tris?: number;
  area?: number;
  /** cable runs (pipe records) behind the length */
  runs?: number;
}

export type ItemSource = 'blocks' | 'triangles' | 'cables' | 'frames' | 'struts';

/** one item's tally inside a source (quantity + the physical measure) */
interface Tally { qty: number; cells: number; metres: number; tris: number; area: number; runs: number }

const newTally = (): Tally => ({ qty: 0, cells: 0, metres: 0, tris: 0, area: 0, runs: 0 });

function tallyAdd(map: Record<string, Tally>, item: string, t: Partial<Tally>) {
  const e = map[item] ?? (map[item] = newTally());
  e.qty += t.qty ?? 0;
  e.cells += t.cells ?? 0;
  e.metres += t.metres ?? 0;
  e.tris += t.tris ?? 0;
  e.area += t.area ?? 0;
  e.runs += t.runs ?? 0;
}

/** the structural tallies: blocks / triangles / cables / frames / struts */
export function structuralItems(bp: Blueprint): Record<ItemSource, Record<string, Tally>> {
  const out: Record<ItemSource, Record<string, Tally>> = {
    blocks: {}, triangles: {}, cables: {}, frames: {}, struts: {},
  };
  const d = bp.data;

  for (const b of d.blocks ?? []) {
    if (b.type === OCCUPANCY_TYPE) continue;      // reservation, not geometry
    const cells = (b.size_x + 1) * (b.size_y + 1) * (b.size_z + 1);
    tallyAdd(out.blocks, blockItem(b.material), { qty: cells, cells });
  }

  for (const tri of d.triangles ?? []) {
    const area = triangleArea(triPoints(tri));
    const cells = area * TRIANGLE_THICKNESS / CELL_VOLUME;
    // the game bills ceil(cells) block items per triangle, never zero
    tallyAdd(out.triangles, blockItem(tri.material), {
      qty: Math.max(Math.ceil(cells), 1), cells, tris: 1, area,
    });
  }

  for (const p of d.pipes ?? []) {
    const item = PIPE_ITEMS[p.type ?? ''];
    if (!item) continue;
    const rec = { qty: 0, metres: 0, runs: 1 };
    for (const seg of p.segments ?? []) {
      const len = seg.length ?? 0;
      // SEGMENT-BY-SEGMENT truncation, exactly like the game (2×1.5 cm = 2 cm)
      rec.qty += Math.trunc(len * 100);
      rec.metres += len;
    }
    tallyAdd(out.cables, `${BUILD_MODULE}.${item}`, rec);
  }

  const frames = d.frames as { beams?: unknown[] }[] | undefined;
  // a FRAME record is a 3 m cube carrying up to 12 beams (the `beams` flags);
  // the game bills ONE SteelBeam per lit beam, not per frame (dev cost.js)
  const beams = (frames ?? []).reduce((n, f) =>
    n + (Array.isArray(f.beams) ? f.beams.filter(Boolean).length : 0), 0);
  if (beams) tallyAdd(out.frames, `${BUILD_MODULE}.SteelBeam`, { qty: beams });

  // STRUTS store two endpoints. MODERN files write them in METRES relative to
  // the frame corner; LEGACY files wrote lattice CELLS and are recognised by
  // an integer v0_x < 32 (the dev viewer's own compatibility probe —
  // js/blueprint.js, transcribed in FORMAT §Struts). The frame corner is
  // f·3 m − 1.5 m, and the offset cancels in the length.
  const struts = d.struts as {
    v0_x?: number; v0_y?: number; v0_z?: number;
    v1_x?: number; v1_y?: number; v1_z?: number;
  }[] | undefined;
  for (const s of struts ?? []) {
    const legacy = Number.isInteger(s.v0_x) && Math.abs(s.v0_x ?? 0) < 32;
    const k = legacy ? CELL : 1;
    const len = Math.hypot(
      ((s.v1_x ?? 0) - (s.v0_x ?? 0)) * k,
      ((s.v1_y ?? 0) - (s.v0_y ?? 0)) * k,
      ((s.v1_z ?? 0) - (s.v0_z ?? 0)) * k);
    tallyAdd(out.struts, `${BUILD_MODULE}.SteelRod`, { qty: Math.ceil(len * 100), metres: len });
  }
  return out;
}

export interface SourceRow {
  item: string;
  /** item count the craft asks for */
  qty: number;
  /** what the quantity measures physically (cells / metres / area …) */
  measure: ItemMeasure;
  /** the whole row's recipe chain (constituents, recursively) */
  node: CostNode;
  /** the whole row unfolded to raw materials */
  total: Cost;
}

export interface BuildSource {
  id: ItemSource;
  title: string;
  /** section summary, e.g. '443 cells · 5 materials' */
  note: string;
  rows: SourceRow[];
}

export interface BuildCost extends CraftCost {
  /** the structural sections (blocks / triangles / cables / frames / struts) */
  sources: BuildSource[];
  /** every structural item the craft asks for, by source */
  structural: Record<ItemSource, Record<string, number>>;
  /** craft-wide physical totals */
  blocks: { records: number; cells: number; materials: number };
  triangles: { tris: number; area: number };
  cables: { runs: number; metres: number };
}

const mText = (m: number): string => `${m.toLocaleString('en', { maximumFractionDigits: 1 })} m`;

/** Full build cost: the parts (componentCosts) PLUS blocks, hull triangles,
 *  cables, frames and struts — every item the game's blueprint tool charges. */
export function buildCost(econ: Economy | null, bp: Blueprint): BuildCost {
  const parts = componentCosts(econ, bp);
  const structural = structuralItems(bp);

  const sources: BuildSource[] = [];
  const total: Cost = { raw: { ...parts.total.raw }, unresolved: { ...parts.total.unresolved }, time: parts.total.time };
  const flat: Record<ItemSource, Record<string, number>> = {
    blocks: {}, triangles: {}, cables: {}, frames: {}, struts: {},
  };

  const push = (id: ItemSource, title: string, note: string, force = false) => {
    const tallies = structural[id];
    for (const [item, t] of Object.entries(tallies)) flat[id][item] = t.qty;
    const rows: SourceRow[] = Object.entries(tallies)
      .filter(([, t]) => t.qty > 0)          // sub-cm cable stubs charge nothing
      .map(([item, t]) => {
        const node = costNode(econ, item, t.qty);
        const rowTotal = node.cost;
        for (const [k, v] of Object.entries(rowTotal.raw)) add(total.raw, k, v);
        for (const [k, v] of Object.entries(rowTotal.unresolved)) add(total.unresolved, k, v);
        total.time += rowTotal.time;
        const measure: ItemMeasure = {};
        if (t.cells) measure.cells = t.cells;
        if (t.metres) measure.metres = t.metres;
        if (t.tris) measure.tris = t.tris;
        if (t.area) measure.area = t.area;
        if (t.runs) measure.runs = t.runs;
        return { item, qty: t.qty, measure, node, total: rowTotal };
      });
    rows.sort((a, b) => b.qty - a.qty);
    if (rows.length || force) sources.push({ id, title, note, rows });
  };

  const blockRecords = (bp.data.blocks ?? []).filter(b => b.type !== OCCUPANCY_TYPE);
  const blockCells = blockRecords.reduce((n, b) => n + (b.size_x + 1) * (b.size_y + 1) * (b.size_z + 1), 0);
  const blockMats = new Set(blockRecords.map(b => b.material ?? 0)).size;
  push('blocks', 'blocks',
    `${blockCells.toLocaleString('en')} cells · ${blockRecords.length.toLocaleString('en')} blocks · ${blockMats} material${blockMats === 1 ? '' : 's'}`);

  const tri = structural.triangles;
  const triCount = Object.values(tri).reduce((n, t) => n + t.tris, 0);
  const triArea = Object.values(tri).reduce((n, t) => n + t.area, 0);
  push('triangles', 'hull triangles',
    `${triCount.toLocaleString('en')} tris · ${triArea.toLocaleString('en', { maximumFractionDigits: 1 })} m²`);

  const cab = structural.cables;
  const cabMetres = Object.values(cab).reduce((n, t) => n + t.metres, 0);
  const cabRuns = Object.values(cab).reduce((n, t) => n + t.runs, 0);
  push('cables', 'cables',
    `${cabRuns.toLocaleString('en')} runs · ${mText(cabMetres)}`, cabRuns > 0);

  const frameBeams = Object.values(structural.frames).reduce((n, t) => n + t.qty, 0);
  const frameRecs = (bp.data.frames as unknown[] | undefined)?.length ?? 0;
  push('frames', 'frames', `${frameBeams} beams · ${frameRecs} frames`);
  push('struts', 'struts', `${(bp.data.struts as unknown[] | undefined)?.length ?? 0} struts`);

  return {
    ...parts,
    sources,
    structural: flat,
    total,
    blocks: { records: blockRecords.length, cells: blockCells, materials: blockMats },
    triangles: { tris: triCount, area: triArea },
    cables: { runs: cabRuns, metres: cabMetres },
  };
}

/** The FULL content list as the game's blueprint tool charges it:
 *  item id → count (parts + blocks + triangles + cables + frames + struts).
 *  This is the parity function for tools/game_data.py `required_items` —
 *  economy.test.ts compares both on the same corpus crafts. */
export function requiredItems(econ: Economy | null, bp: Blueprint): Record<string, number> {
  const out: Record<string, number> = {};
  for (const e of componentEntries(econ, bp)) add(out, e.id, e.count);
  for (const map of Object.values(structuralItems(bp)))
    for (const [id, t] of Object.entries(map)) if (t.qty > 0) add(out, id, t.qty);
  return out;
}

// ------------------------------------------------------------------- loader
let econP: Promise<Economy | null> | null = null;

/** The shipped economy table (viewer/models/economy.json). Resolved through
 *  the SAME layout-exact base candidates as the model atlas; a failed load is
 *  NOT cached (a snag must not kill the section for the session) and the
 *  widget simply hides itself while `null`. */
export function loadEconomy(): Promise<Economy | null> {
  econP ??= (async () => {
    for (const path of atlasJsonPaths('economy.json')) {
      try {
        const r = await fetch(path);
        if (!r.ok) continue;
        const j = await r.json() as Partial<Economy>;
        if (j && j.recipes && j.components) return j as Economy;
      } catch { /* next candidate */ }
    }
    return null;
  })().then(e => { if (!e) econP = null; return e; });
  return econP;
}
